// 원문 메타128행과 실제 C++ 메타/버튼 본체의 현재 필드·8192BYTE·순서를 대조한다.
#include "TestSupport.h"
#include "client/HtmlWindowMetadata.h"
#include <bit>
#include <cstdio>
#include <fstream>
#include <map>
using namespace netstorm::client;
namespace { // 입력/관측과 명시 하위 장치만 다룬다.
std::vector<std::string> MetaSplit(std::string_view text,char separator) { std::vector<std::string> result;std::size_t begin{};for (;;) { const auto end=text.find(separator,begin);result.emplace_back(text.substr(begin,end==text.npos ? text.npos : end-begin));if (end==text.npos) return result;begin=end+1; } } // 빈 열도 보존한다.
std::string MetaBytes(std::string_view source) { std::string result;for (std::size_t index=0;index<source.size();index+=2) result+=static_cast<char>(std::stoul(std::string(source.substr(index,2)),nullptr,16));return result; } // 독립 원시 입력을 해석한다.
std::string MetaHex(std::string_view bytes) { const char digits[]="0123456789abcdef";std::string result;for (const auto byte:bytes) { const auto value=static_cast<unsigned char>(byte);result+=digits[value>>4];result+=digits[value&15]; }return result; } // 실제 문자열 바이트의 관측이다.
std::string MetaPack(const std::vector<std::uint32_t>& values) { std::string result;for (const auto value:values) { if (!result.empty()) result+=':';result+=std::to_string(value); }return result; } // 실제 DWORD 관측이다.
struct MetaStop {}; // 명시 선택 중단을 정상 반환과 구별한다.
}

// 실제 원문은 regexp compile/search를 명시 하위로 두며 캡처/시작점/버튼/버퍼 상위를 실행했다.
TEST_CASE(HtmlWindowMetadata_IndependentNativePriorityEffectsAndPhysicalBuffer) {
    std::ifstream input(NETSTORM_HTML_METADATA_FIXTURE);CHECK(input.good());std::string line;std::getline(input,line);std::size_t rows{};
    while (std::getline(input,line)) { // 각 원문 입력을 새 실제 부모/버튼/물리 버퍼에 설치한다.
        if (!line.empty() && line.back()=='\r') line.pop_back();const auto f=MetaSplit(line,'\t');CHECK(f.size()==22);if (f.size()!=22) continue;HtmlWindowGumpNode node;node.flags=9;node.controlCount=2;node.menuColumns=static_cast<std::uint32_t>(std::stoul(f[4]));node.timeoutSeconds=0;node.timeoutCommand=0;node.timeoutParameter=0xa5a5a5a5;node.onExitCommand=0;node.onExitParameter=0x5a5a5a5a;
        for (auto& entry:node.controls) entry={0,0,0};node.controls[0]={2,7,8};node.controls[1]={3,7,8};std::map<std::uint32_t,ButtonGumpNode> children;children[2];children[3];std::uint32_t nextChild{4},closed{0x020000be};std::vector<std::string> trace,stores; // 명시 하위의 실제 현재 저장소다.
        const auto event=[&](std::string_view name,std::string args=std::string{}) { // 실제 장치 효과 뒤에만 독립 입력의 변경/중단을 적용한다.
            trace.push_back(std::string(name)+(args.empty() ? "" : ':'+args));if (f[10]!="-") { const auto mutation=MetaSplit(f[10],'.');if (name==mutation[0]) { if (mutation[1]=="columns") node.menuColumns=static_cast<std::uint32_t>(std::stoul(mutation[2]));else { CHECK(mutation[1]=="closed");closed=static_cast<std::uint32_t>(std::stoul(mutation[2])); } } }if (f[11]==name) throw MetaStop{};
        };
        HtmlWindowGumpState window;HtmlWindowGumpHooks coreHooks;coreHooks.node=[&](auto token) { return token==1 ? &node : nullptr; };coreHooks.base=[&](auto token)->GumpCreateNode* { if (token==1) return &node;const auto found=children.find(token);return found==children.end() ? nullptr : &found->second; };coreHooks.button=[&](auto token) { return &children.at(token); };coreHooks.kill=[&](auto token) { event("kill",std::to_string(token)); };coreHooks.allocate=[&](auto bytes) { CHECK(bytes==0x170);const auto token=nextChild++;children[token];return token; };
        coreHooks.constructButton=[&](auto token,auto label) { children.at(token).buttonFlags=0;event("button",std::to_string(token)+':'+MetaHex(label)); };coreHooks.attach=[&](auto token,float x,float y,auto parent,auto mode) { event("attach",MetaPack({token,std::bit_cast<std::uint32_t>(x),std::bit_cast<std::uint32_t>(y),parent,mode})); };HtmlWindowGump core(window,std::move(coreHooks));
        HtmlWindowMetadataHooks h;h.node=[&](auto token) { return token==1 ? &node : nullptr; };h.clearButtons=[&](auto token) { core.ClearButtons(token); };h.addButton=[&](auto token,auto label,auto command,auto parameter,auto instant) { core.AddButton(token,label,command,parameter,instant); };
        h.commands.lookup=[&](auto name) { event("lookup",MetaHex(name));return static_cast<std::uint32_t>(std::stoul(f[9])); };h.commands.unknown=[&](auto name) { event("diagnostic",MetaHex(name)); };h.storeText=[&](auto bytes) { stores.push_back(MetaHex(bytes));const auto token=0x60000000U+static_cast<std::uint32_t>(stores.size());event("store",MetaHex(bytes));return token; };
        h.beginMenu=[&](auto flags) { event("begin",std::to_string(flags)); };h.menuText=[&](auto label,auto command,auto parameter) { event("text",MetaHex(label)+':'+MetaPack({command,parameter,1,1,0})); };h.checked=[&](auto checked,auto label,auto command,auto parameter,bool enabled) { event("checked",std::to_string(static_cast<std::uint32_t>(checked))+':'+MetaHex(label)+':'+MetaPack({command,parameter,1,enabled ? 1U : 0U})); };
        h.maps=[&](auto label,auto&) { const auto key=label=="*SOLOLIST*" ? 2U : 0U;event("mapRefresh",std::to_string(key));event("mapRow","0"); };h.tech=[&](auto parameter) { event("tech",std::to_string(parameter)); };h.themeTech=[&](auto low,auto high) { event("theme",MetaPack({low,static_cast<std::uint32_t>(high)})); };
        h.namedList=[&](auto key,auto command,auto argument) { event("named",MetaHex(key)+':'+std::to_string(command)+':'+MetaHex(argument)); };h.fileList=[&](auto key,auto command,auto argument) { event("files",MetaHex(key)+':'+std::to_string(command)+':'+MetaHex(argument)); };h.inlineList=[&](auto key,auto command,auto argument) { event("inline",MetaHex(key)+':'+MetaHex(command)+':'+MetaHex(argument));return MetaBytes(f[8]); };
        h.wallSeconds=[&] { event("clock");return std::stod(f[7]); };h.idle=[&](auto token,bool enabled) { node.flags=enabled ? node.flags|0x80U : node.flags&~0x80U;event("idle",MetaPack({token,enabled ? 1U : 0U})); };h.read=[&](auto address) { if (address==0x5cab30U) return static_cast<std::uint32_t>(std::stoul(f[5]));if (address==0x55a480U) return static_cast<std::uint32_t>(std::stoul(f[6]));CHECK(address==0x5429ecU);return closed; };
        h.input=[&](auto limit,auto label,auto argument) { event("input",std::to_string(static_cast<std::uint32_t>(limit))+':'+MetaHex(label)+':'+MetaHex(argument)); };h.send=[&](auto label,auto command,auto argument) { event("send",MetaHex(label)+':'+MetaHex(command)+':'+MetaHex(argument)); };h.queue=[&](auto command,auto first,auto second) { event("queue",MetaPack({command,first,second})); };
        std::array<char,8192> buffer;buffer.fill(static_cast<char>(std::stoul(f[3])));const auto source=MetaBytes(f[2]);std::copy(source.begin(),source.end(),buffer.begin());buffer[source.size()]=0;HtmlWindowMetadata metadata(std::move(h));bool completed=true;std::uint32_t result{};try { result=metadata.Process(1,buffer); }catch (const MetaStop&) { completed=false; }
        const auto time=std::bit_cast<std::uint64_t>(node.timeoutSeconds);const std::vector<std::uint32_t> fields{node.flags,node.controlCount,node.menuColumns,static_cast<std::uint32_t>(time),static_cast<std::uint32_t>(time>>32),node.timeoutCommand,node.timeoutParameter,node.onExitCommand,node.onExitParameter};std::vector<std::uint32_t> slots;for (const auto& entry:node.controls) { slots.push_back(entry.child);slots.push_back(entry.command);slots.push_back(entry.parameter); } // 모든 현재 실제 부모/행이다.
        std::uint64_t fingerprint=14695981039346656037ULL;for (const auto byte:buffer) fingerprint=(fingerprint^static_cast<unsigned char>(byte))*1099511628211ULL;std::string calls,stored;for (const auto& call:trace) { if (!calls.empty()) calls+=';';calls+=call; }for (const auto& value:stores) { if (!stored.empty()) stored+=';';stored+=value; } // 실제 전체 물리/장치/고리 관측이다.
        const auto end=std::find(buffer.begin(),buffer.end(),'\0');CHECK(end!=buffer.end());const auto output=MetaHex(std::string_view(buffer.data(),static_cast<std::size_t>(end-buffer.begin())));const bool same=completed==(f[12]=="1") && MetaPack(fields)==f[13] && MetaPack(slots)==f[14] && fingerprint==std::stoull(f[15]) && output==f[16] && stored==f[17] && calls==f[18] && (completed ? result : 0)==std::stoul(f[19]);if (!same) std::fprintf(stderr,"HTML metadata mismatch %s actual=%s expected=%s\n",f[0].c_str(),calls.c_str(),f[18].c_str());CHECK(same);++rows;
    }
    CHECK(rows==128);
}
